#!/usr/bin/env node
// 第一行是 shebang：系统看到它，就用 node 来执行这个文件。它必须独占第一行。

/**
 * 用 `.env.production.local` 里的配置，启动 Next.js 开发服务器。
 *
 * `next dev` 自己会热更新，但不会读取 `.env.production.local`。
 * 这个脚本先把那个文件里的变量放进子进程，让它们盖过 `.env.local`。
 * `NODE_ENV` 固定为 `development`，否则开发服务器不能热更新。
 *
 * 用法：
 *   pnpm run prod:dev
 *   pnpm run prod:dev -- -p 3001
 */

// 引入 spawn：用来再启动一个进程，这里启动的是 next dev。
import { spawn } from "node:child_process";
// 引入文件系统模块：检查 env 文件在不在，并把文件内容读出来。
import * as fs from "fs";
// 引入路径模块：把目录和文件名拼成完整路径。
import * as path from "path";

// 读取一个 env 文件，解析成「变量名 -> 变量值」。
const loadEnvFile = (filePath: string): Record<string, string> => {
  // 先放一个空对象，解析出来的变量都写到这里。
  const env: Record<string, string> = {};
  // 按 UTF-8 把整个文件一次性读成字符串。
  const content = fs.readFileSync(filePath, "utf-8");

  // 按换行拆开，一行一行看。
  for (const line of content.split("\n")) {
    // 去掉这一行开头和结尾的空白。
    const trimmed = line.trim();
    // 空行，或者以 # 开头的注释行，都不当成变量。
    if (!trimmed || trimmed.startsWith("#")) continue;

    // 匹配「名字=值」。等号左边是名字，右边整段都是值，值里还可以再有等号。
    const match = trimmed.match(/^([^=]+)=(.*)$/);
    // 这一行不是「名字=值」就跳过。
    if (!match) continue;

    // match[1] 是变量名，再去掉两侧空白。
    const key = match[1].trim();
    // match[2] 是变量值，再去掉两侧空白。
    let value = match[2].trim();

    // 值被一对引号整个包住时，去掉这对引号。双引号、单引号都可以。
    if (
      (value.startsWith('"') && value.endsWith('"')) || // 整段被双引号包住
      (value.startsWith("'") && value.endsWith("'")) // 整段被单引号包住
    ) {
      // slice(1, -1) 去掉第一个和最后一个字符，也就是那对引号。
      value = value.slice(1, -1);
    }

    // 把这一对变量存进结果。同名时，文件后面的行会盖住前面的行。
    env[key] = value;
  }

  // 把解析好的变量对象交回去。
  return env;
};

// 正式 prod Supabase 项目的固定编号。后面用它确认数据库地址确实指向 prod。
const PROD_SUPABASE_PROJECT_REF = "kshrgedtoxsiotgzrcru";
// 这两条是数据库连接串，都必须包含上面的 prod 项目编号。
const DATA_ENV_KEYS = ["DATABASE_URL", "DIRECT_URL"] as const;

// 拼出「当前目录/.env.production.local」。pnpm 在项目根执行时，当前目录就是项目根。
const envFilePath = path.join(process.cwd(), ".env.production.local");

// 文件不存在就立刻停止，避免在没有 prod 配置时误连别的库。
if (!fs.existsSync(envFilePath)) {
  // 把缺文件这件事打到终端的错误输出。
  console.error("prod:dev: missing .env.production.local");
  // 退出码 1 表示失败。后面的代码不会再执行。
  process.exit(1);
}

// 读取并解析 .env.production.local。
const fileEnv = loadEnvFile(envFilePath);
// 收集要注入的变量名。NODE_ENV 排除掉，因为下面会强制写成 development。
const injectedKeys = Object.keys(fileEnv).filter((key) => key !== "NODE_ENV");

// 除了 NODE_ENV 以外一个变量都没有，说明文件是空的，或只剩注释。
if (injectedKeys.length === 0) {
  // 提示文件里没有可注入的变量。
  console.error("prod:dev: .env.production.local has no variables to inject");
  // 同样以失败退出，不启动 next。
  process.exit(1);
}

// 逐条检查两条数据库连接串。
for (const key of DATA_ENV_KEYS) {
  // 取出这一条的值。文件里没写这个名字时，value 是 undefined。
  const value = fileEnv[key];

  // ?. 表示 value 为空时不再调用 includes。没有值，或值里没有 prod 项目编号，都拒绝启动。
  if (!value?.includes(PROD_SUPABASE_PROJECT_REF)) {
    // 用模板字符串指出是哪一个变量没有指向 prod。
    console.error(
      `prod:dev: ${key} in .env.production.local must point at the prod Supabase project`,
    );
    // 校验失败就退出，避免开发服务器连到非 prod 数据库。
    process.exit(1);
  }
}

// 先复制当前这个进程已经有的环境变量，作为子进程环境的底稿。
const childEnv: NodeJS.ProcessEnv = { ...process.env };

// 先删掉从父进程继承来的两条数据库地址，避免旧的 dev 库地址留下来。
for (const key of DATA_ENV_KEYS) {
  // delete 只删子进程这份副本，不改当前终端已经导出的变量。
  delete childEnv[key];
}

// 再把文件里的变量写进子进程。同名变量以文件里的值为准。
for (const key of injectedKeys) {
  // 这样 .env.production.local 会盖过父进程和 .env.local 里的同名值。
  childEnv[key] = fileEnv[key];
}

// 不管文件里 NODE_ENV 写成什么，这里都改回 development，next dev 才能热更新。
childEnv.NODE_ENV = "development";

// APP_ENV 只承认 dev 或 prod。没写，或写成别的，日志里就显示 unrecognized。
const appEnv = childEnv.APP_ENV === "dev" || childEnv.APP_ENV === "prod" ? childEnv.APP_ENV : "unrecognized";

// 打印一共注入了多少个变量，方便确认文件真的被读到了。
console.log(`prod:dev: injected ${injectedKeys.length} variables from .env.production.local`);
// 打印业务环境 APP_ENV，并说明 NODE_ENV 为什么仍是 development。
console.log(`prod:dev: APP_ENV=${appEnv}; NODE_ENV=development so the dev server can hot reload`);
// 打印数据库地址已经被钉在 prod Supabase 项目上。这里不打印连接串本身。
console.log(
  "prod:dev: DATABASE_URL and DIRECT_URL are pinned to the prod Supabase project",
);

// 拼出项目本地安装的 next 命令入口，不使用电脑上全局安装的 next。
const nextBin = path.join(process.cwd(), "node_modules", "next", "dist", "bin", "next");
// process.execPath 是当前正在跑的 node。process.argv.slice(2) 是你在命令后额外加的参数，例如 -p 3001。
const child = spawn(process.execPath, [nextBin, "dev", ...process.argv.slice(2)], {
  // 子进程的工作目录仍是项目根，next 才能找到 app、配置和 env。
  cwd: process.cwd(),
  // 把上面组装好的环境变量交给 next，而不是让它只继承默认环境。
  env: childEnv,
  // 子进程和当前终端共用输入输出。next 的日志直接显示，Ctrl+C 也能传进去。
  stdio: "inherit",
});

// next 退出时，这个脚本也要退出，不能变成一个空等的父进程。
child.on("exit", (code, signal) => {
  // signal 有值，表示 next 是被信号关掉的，例如 SIGINT。
  if (signal) {
    // 给当前脚本进程发送同一个信号，让外层看到的退出原因和 next 一致。
    process.kill(process.pid, signal);
    // 信号已经发出，这个回调到这里结束。
    return;
  }

  // 没被信号杀掉时，沿用 next 的退出码。code 为空就用 1，表示异常退出。
  process.exit(code ?? 1);
});

// 收到停止信号时，把同一个信号转给 next 子进程。
const stopChild = (signal: NodeJS.Signals): void => {
  // child.kill 不会杀掉当前脚本自己，只通知 next 退出。
  child.kill(signal);
};

// 你按 Ctrl+C 时，终端会发 SIGINT。这里转给 next，让开发服务器先停。
process.on("SIGINT", () => stopChild("SIGINT"));
// 终端关闭、进程管理器或 pnpm 要求退出时，会发 SIGTERM，同样转给 next。
process.on("SIGTERM", () => stopChild("SIGTERM"));
